install.linux:
cd "$WEFT_NEED_DIR"
fetch https://cursor.com/install installer.sh
url=$(sed -n 's/^DOWNLOAD_URL="\(.*\)"$/\1/p' installer.sh)
[ -n "$url" ] || { echo "Cursor's installer (https://cursor.com/install) no longer names its download as DOWNLOAD_URL=\"...\"" >&2; exit 1; }
url=${url//\$\{OS\}/$(weft_os)}
url=${url//\$\{ARCH\}/$(weft_arch)}
fetch "$url" agent.tar.gz
rm -rf dist && extract agent.tar.gz dist 1
mkdir -p bin && ln -sfn ../dist/cursor-agent bin/agent
rm agent.tar.gz installer.sh

