install.linux:
case $(weft_os)-$(weft_arch) in
    linux-x64) target=x86_64-unknown-linux ;;
    linux-arm64) target=aarch64-unknown-linux ;;
    darwin-x64) target=x86_64-apple-darwin ;;
    darwin-arm64) target=aarch64-apple-darwin ;;
esac
cd "$WEFT_NEED_DIR"
fetch https://static.devin.ai/cli/current/manifest.json manifest.json
fetch "$(json_get manifest.json "j['platforms']['$target']['url']")" devin.tar.gz
check_sha256 devin.tar.gz "$(json_get manifest.json "j['platforms']['$target']['sha256']")"
rm -rf devin && extract devin.tar.gz devin
echo curl-bash > devin/distribution
rm devin.tar.gz manifest.json

