install.linux:
# Kimi Code's SDK is not published: build it, with its engine, from Kimi Code's source at one release, on weft's Node 24.
TAG="@moonshot-ai/kimi-code@2.5.1"
D="$WEFT_NEED_DIR"
node_bin=$(need_node 24)
fetch "https://github.com/MoonshotAI/kimi-code/archive/refs/tags/$TAG.tar.gz" "$D/src.tar.gz"
extract "$D/src.tar.gz" "$D/src" 1
rm "$D/src.tar.gz"
# corepack, pnpm and everything they keep, in this folder.
export PATH="$node_bin:$PATH" COREPACK_ENABLE_DOWNLOAD_PROMPT=0 COREPACK_HOME="$D/.corepack" npm_config_cache="$D/.npm" \
  XDG_CACHE_HOME="$D/.xdg/cache" XDG_DATA_HOME="$D/.xdg/data" XDG_STATE_HOME="$D/.xdg/state" XDG_CONFIG_HOME="$D/.xdg/config"
cd "$D/src"
corepack pnpm install --frozen-lockfile --ignore-scripts --store-dir "$D/src/.store" --filter "@moonshot-ai/kimi-code-sdk..."
cd packages/node-sdk
cat > weft-host.ts <<TS
// weft's host of Kimi Code's SDK: runs a module's main(sdk, engine, args) on this one build of the SDK and its engine.
// SYNC: main(sdk, engine, args) <-> catalog/agents/server/kimi_bridge.mjs (main)
import { pathToFileURL } from 'node:url';
import * as sdk from './src/index.ts';
import * as engine from '@moonshot-ai/agent-core-v2';
const [what, ...rest] = process.argv.slice(2);
if (what === '--version') console.log('kimi-code-sdk $TAG');
else if (what === undefined) { console.error('usage: kimi-code-sdk <module.mjs> [args...] | --version'); process.exit(2); }
else await (await import(pathToFileURL(what).href)).main(sdk, engine, rest);
TS
cat > weft-host.config.ts <<TS
import { defineConfig } from 'tsdown';
import base from './tsdown.config.ts';
export default defineConfig({ ...base, entry: ['./weft-host.ts'], outDir: 'weft-host', deps: { alwaysBundle: [/./], neverBundle: [] } });
TS
corepack pnpm exec tsdown --config weft-host.config.ts
mv weft-host "$D/host"
cd "$D" && rm -rf src .corepack .npm .xdg
mkdir -p bin
printf '#!/bin/sh\nexec "%s/node" "%s/host/weft-host.mjs" "$@"\n' "$node_bin" "$D" > bin/kimi-code-sdk
chmod +x bin/kimi-code-sdk

